// Extract and normalize guest information
const message = $input.item(0, 0).json.message || '';
const guestEmail = $input.item(0, 0).json.guestEmail || '';
const bookingReference = $input.item(0, 0).json.bookingReference || '';
const guestName = $input.item(0, 0).json.guestName || '';

// Generate conversation ID for tracking
const conversationId = `conv_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

// Classify request type for better handling
const requestType = classifyRequest(message);

function classifyRequest(msg) {
  const msgLower = msg.toLowerCase();

  if (msgLower.includes('check-in') || msgLower.includes('checkin') || msgLower.includes('arrival')) return 'checkin';
  if (msgLower.includes('check-out') || msgLower.includes('checkout') || msgLower.includes('departure')) return 'checkout';
  if (msgLower.includes('booking') || msgLower.includes('reservation') || msgLower.includes('confirm')) return 'booking';
  if (msgLower.includes('cancel') || msgLower.includes('modify') || msgLower.includes('change')) return 'modification';
  if (msgLower.includes('available') || msgLower.includes('vacancy') || msgLower.includes('book')) return 'availability';
  if (msgLower.includes('amenity') || msgLower.includes('facility') || msgLower.includes('service')) return 'amenities';
  if (msgLower.includes('location') || msgLower.includes('direction') || msgLower.includes('address')) return 'location';
  if (msgLower.includes('wifi') || msgLower.includes('internet') || msgLower.includes('password')) return 'technical';
  if (msgLower.includes('price') || msgLower.includes('cost') || msgLower.includes('rate') || msgLower.includes('payment')) return 'pricing';

  return 'general';
}

return {
  conversationId,
  guestInfo: {
    email: guestEmail,
    name: guestName,
    bookingReference
  },
  request: {
    message,
    type: requestType,
    timestamp: new Date().toISOString(),
    language: detectLanguage(message)
  }
};

function detectLanguage(text) {
  // Simple language detection - can be enhanced
  const spanishWords = ['hola', 'gracias', 'por favor', 'disculpe'];
  const frenchWords = ['bonjour', 'merci', 'excusez-moi', 'sil vous plait'];
  const germanWords = ['hallo', 'danke', 'entschuldigung', 'bitte'];

  const textLower = text.toLowerCase();

  if (spanishWords.some(word => textLower.includes(word))) return 'es';
  if (frenchWords.some(word => textLower.includes(word))) return 'fr';
  if (germanWords.some(word => textLower.includes(word))) return 'de';

  return 'en'; // Default to English
}

// Format the AI response and prepare for delivery
const aiResponse = $input.item(0, 0).json.output;
const guestInfo = $('Process Guest Information').item(0, 0).json.guestInfo;
const conversationId = $('Process Guest Information').item(0, 0).json.conversationId;
const timestamp = new Date().toISOString();

// Log the interaction for analytics and training
const interactionLog = {
  conversationId,
  timestamp,
  guestEmail: guestInfo.email,
  guestName: guestInfo.name,
  bookingReference: guestInfo.bookingReference,
  originalMessage: $('Process Guest Information').item(0, 0).json.request.message,
  requestType: $('Process Guest Information').item(0, 0).json.request.type,
  aiResponse: aiResponse,
  language: $('Process Guest Information').item(0, 0).json.request.language,
  responseTime: Date.now() - new Date($('Process Guest Information').item(0, 0).json.request.timestamp).getTime()
};

// Format final response
const formattedResponse = {
  success: true,
  response: aiResponse,
  conversationId,
  timestamp,
  metadata: {
    guestEmail: guestInfo.email,
    language: $('Process Guest Information').item(0, 0).json.request.language,
    responseType: 'ai_generated'
  }
};

return {
  response: formattedResponse,
  log: interactionLog
};

