// Automatic refresh token management
// This runs every 30 minutes to ensure tokens stay fresh

const currentToken = $input.item(0, 0).json.refreshToken;
const tokenTimestamp = $input.item(0, 0).json.timestamp || Date.now();
const now = Date.now();

// Check if token is older than 25 minutes (refresh before 30min expiry)
const tokenAge = now - tokenTimestamp;
const refreshThreshold = 25 * 60 * 1000; // 25 minutes in milliseconds

if (tokenAge > refreshThreshold) {
  console.log('Refresh token is expiring soon, triggering renewal');
  return [{ needsRefresh: true, currentToken }];
} else {
  console.log('Refresh token is still valid');
  return [{ needsRefresh: false, currentToken }];
}
